1	package fleet
2	
3	import (
4		"encoding/binary"
5		"fmt"
6		"net/http"
7		"os"
8		"path/filepath"
9		"strings"
10		"sync"
11		"testing"
12		"time"
13	)
14	
15	// --- helpers ---------------------------------------------------------------
16	
17	func openPersistent(t *testing.T, dir string) *Store {
18		t.Helper()
19		store, err := NewPersistentStore(dir)
20		if err != nil {
21			t.Fatalf("open %s: %v", dir, err)
22		}
23		clock := time.Date(2024, time.January, 1, 0, 0, 0, 0, time.UTC)
24		store.now = func() time.Time { return clock }
25		t.Cleanup(func() { _ = store.Close() })
26		return store
27	}
28	
29	func reopenPersistent(t *testing.T, dir string) *Store {
30		t.Helper()
31		store, err := NewPersistentStore(dir)
32		if err != nil {
33			t.Fatalf("reopen %s: %v", dir, err)
34		}
35		clock := time.Date(2025, time.June, 1, 0, 0, 0, 0, time.UTC)
36		store.now = func() time.Time { return clock }
37		t.Cleanup(func() { _ = store.Close() })
38		return store
39	}
40	
41	func walRaw(t *testing.T, dir string) []byte {
42		t.Helper()
43		raw, err := os.ReadFile(filepath.Join(dir, walName))
44		if err != nil {
45			t.Fatalf("read wal: %v", err)
46		}
47		return raw
48	}
49	
50	func commitRaw(t *testing.T, dir string) []byte {
51		t.Helper()
52		raw, err := os.ReadFile(filepath.Join(dir, commitName))
53		if err != nil {
54			t.Fatalf("read commit journal: %v", err)
55		}
56		return raw
57	}
58	
59	// frameEnd walks one frame [length][type][payload][crc32] at pos.
60	func frameEnd(t *testing.T, data []byte, pos int) int {
61		t.Helper()
62		length := int(binary.LittleEndian.Uint32(data[pos : pos+4]))
63		return pos + 5 + length + 4
64	}
65	
66	// --- restart restores everything ------------------------------------------
67	
68	func TestPersistentRestartRestoresState(t *testing.T) {
69		dir := t.TempDir()
70		store := openPersistent(t, dir)
71		h := NewHandler(store)
72		mustRegister(t, h, "gw")
73	
74		firstClock := store.now().Add(10 * time.Second)
75		store.now = func() time.Time { return firstClock }
76		if r := doRequest(t, h, http.MethodPost, "/v1/devices/gw/telemetry", `{"temperature":20}`); r.Code != http.StatusAccepted {
77			t.Fatalf("telemetry = %d", r.Code)
78		}
79	
80		// A mixed batch: one new sample plus one duplicate of an earlier event.
81		if r := doRequest(t, h, http.MethodPost, "/v1/devices/gw/replay",
82			replayBody("batch-a", sample("e1", "2024-01-02T10:00:00Z", `{"v":1}`))); r.Code != http.StatusAccepted {
83			t.Fatalf("batch-a = %d", r.Code)
84		}
85		if r := doRequest(t, h, http.MethodPost, "/v1/devices/gw/replay",
86			replayBody("batch-b",
87				sample("e1", "2024-01-02T18:00:00+08:00", `{"v":1}`),
88				sample("e2", "2024-01-02T11:00:00Z", `{"v":2}`),
89			)); r.Code != http.StatusAccepted {
90			t.Fatalf("batch-b = %d", r.Code)
91		}
92		if err := store.Close(); err != nil {
93			t.Fatal(err)
94		}
95	
96		// Recovery uses a later clock; device timestamps must not be refreshed.
97		store2 := reopenPersistent(t, dir)
98		h2 := NewHandler(store2)
99	
100		snapshot := decodeBody[struct {
101			Devices []Device `json:"devices"`
102		}](t, doRequest(t, h2, http.MethodGet, "/v1/fleet", ""))
103		if len(snapshot.Devices) != 1 {
104			t.Fatalf("devices = %+v", snapshot.Devices)
105		}
106		got := snapshot.Devices[0]
107		if got.ID != "gw" || got.RegisteredAt.UTC() != time.Date(2024, time.January, 1, 0, 0, 0, 0, time.UTC) {
108			t.Fatalf("registration not restored: %+v", got)
109		}
110		if got.LastSeenAt.Equal(store2.now()) {
111			t.Fatalf("recovery refreshed lastSeenAt to %s", got.LastSeenAt)
112		}
113		if got.LastTelemetry["v"] != 2 {
114			t.Fatalf("lastTelemetry = %+v, want v:2", got.LastTelemetry)
115		}
116	
117		events := allEvents(t, h2, "gw")
118		if len(events) != 3 {
119			t.Fatalf("history = %d events, want 3: %+v", len(events), events)
120		}
121		for i, event := range events {
122			if event.Sequence != int64(i+1) {
123				t.Fatalf("sequence %d = %d", i, event.Sequence)
124			}
125		}
126	
127		// New samples continue the sequence after restart.
128		if r := doRequest(t, h2, http.MethodPost, "/v1/devices/gw/telemetry", `{"temperature":25}`); r.Code != http.StatusAccepted {
129			t.Fatalf("post-restart telemetry = %d", r.Code)
130		}
131		events = allEvents(t, h2, "gw")
132		if len(events) != 4 || events[3].Sequence != 4 {
133			t.Fatalf("sequence did not continue after restart: %+v", events)
134		}
135	
136		// Replaying a previously accepted batch returns the first receipt (200);
137		// changed content still conflicts.
138		firstReceipt := `{"batchId":"batch-a","newCount":1,"duplicateCount":0,"samples":[{"eventId":"e1","sequence":2,"duplicate":false}]}`
139		r := doRequest(t, h2, http.MethodPost, "/v1/devices/gw/replay",
140			replayBody("batch-a", sample("e1", "2024-01-02T10:00:00Z", `{"v":1}`)))
141		if r.Code != http.StatusOK {
142			t.Fatalf("repeat batch = %d, want 200: %s", r.Code, r.Body.String())
143		}
144		if compact(r.Body.String()) != firstReceipt {
145			t.Fatalf("receipt changed: %s want %s", compact(r.Body.String()), firstReceipt)
146		}
147		r = doRequest(t, h2, http.MethodPost, "/v1/devices/gw/replay",
148			replayBody("batch-a", sample("e1", "2024-01-02T10:00:00Z", `{"v":9}`)))
149		if r.Code != http.StatusConflict {
150			t.Fatalf("changed batch = %d, want 409", r.Code)
151		}
152	
153		// Per-device dedupe still holds after restart.
154		r = doRequest(t, h2, http.MethodPost, "/v1/devices/gw/replay",
155			replayBody("batch-c",
156				sample("e2", "2024-01-02T11:00:00Z", `{"v":2}`),
157				sample("e3", "2024-01-02T12:00:00Z", `{"v":3}`),
158			))
159		if r.Code != http.StatusAccepted {
160			t.Fatalf("batch-c = %d: %s", r.Code, r.Body.String())
161		}
162		receipt := decodeBody[receiptResponse](t, r)
163		if receipt.NewCount != 1 || receipt.DuplicateCount != 1 ||
164			receipt.Samples[0].Sequence != 3 || !receipt.Samples[0].Duplicate ||
165			receipt.Samples[1].Sequence != 5 || receipt.Samples[1].Duplicate {
166			t.Fatalf("post-restart dedupe receipt = %+v", receipt.Samples)
167		}
168	}
169	
170	func compact(jsonBody string) string {
171		return strings.NewReplacer(" ", "", "\n", "").Replace(strings.TrimSpace(jsonBody))
172	}
