184	// --- cursors survive restart but not a different data directory ------------
185	
186	func TestPersistentCursorSurvivesRestart(t *testing.T) {
187		dir := t.TempDir()
188		store := openPersistent(t, dir)
189		h := NewHandler(store)
190		mustRegister(t, h, "gw")
191		for i := 0; i < 3; i++ {
192			if r := doRequest(t, h, http.MethodPost, "/v1/devices/gw/replay",
193				replayBody(fmt.Sprintf("b%d", i), sample(fmt.Sprintf("e%d", i), "2024-01-02T10:00:00Z", fmt.Sprintf(`{"v":%d}`, i)))); r.Code != http.StatusAccepted {
194				t.Fatalf("seed %d = %d", i, r.Code)
195			}
196		}
197		first := doRequest(t, h, http.MethodGet, "/v1/devices/gw/history?limit=1", "")
198		page := decodeBody[historyResponse](t, first)
199		if page.NextCursor == nil {
200			t.Fatalf("expected cursor")
201		}
202		originalCursor := *page.NextCursor
203		cursor := originalCursor
204	
205		// Add samples, restart: the pinned walk must still end at sequence 3.
206		for i := 3; i < 6; i++ {
207			if r := doRequest(t, h, http.MethodPost, "/v1/devices/gw/replay",
208				replayBody(fmt.Sprintf("b%d", i), sample(fmt.Sprintf("e%d", i), "2024-01-02T10:00:00Z", fmt.Sprintf(`{"v":%d}`, i)))); r.Code != http.StatusAccepted {
209				t.Fatalf("extra %d = %d", i, r.Code)
210			}
211		}
212		if err := store.Close(); err != nil {
213			t.Fatal(err)
214		}
215		store2 := reopenPersistent(t, dir)
216		h2 := NewHandler(store2)
217	
218		seen := page.Events
219		for cursor != "" {
220			r := doRequest(t, h2, http.MethodGet, "/v1/devices/gw/history?limit=1&cursor="+cursor, "")
221			if r.Code != http.StatusOK {
222				t.Fatalf("paged status = %d: %s", r.Code, r.Body.String())
223			}
224			next := decodeBody[historyResponse](t, r)
225			seen = append(seen, next.Events...)
226			if next.NextCursor == nil {
227				cursor = ""
228			} else {
229				cursor = *next.NextCursor
230			}
231		}
232		if len(seen) != 3 {
233			t.Fatalf("pinned walk after restart saw %d events, want 3: %+v", len(seen), seen)
234		}
