236		// The same cursor presented to a different rebuilt data directory (even
237		// with the same device id) is 400.
238		other := openPersistent(t, t.TempDir())
239		otherH := NewHandler(other)
240		mustRegister(t, otherH, "gw")
241		if r := doRequest(t, otherH, http.MethodGet, "/v1/devices/gw/history?limit=1&cursor="+originalCursor, ""); r.Code != http.StatusBadRequest {
242			t.Fatalf("foreign-dir cursor = %d, want 400", r.Code)
243		}
244	}
