246	// --- inter-process directory lock ------------------------------------------
247	
248	func TestPersistentDirectoryLockExclusive(t *testing.T) {
249		dir := t.TempDir()
250		first := openPersistent(t, dir)
251	
252		if _, err := NewPersistentStore(dir); err == nil {
253			t.Fatalf("second open of %s succeeded while first was live", dir)
254		} else if !strings.Contains(err.Error(), "already in use") {
255			t.Fatalf("second open error = %v, want lock message", err)
256		}
