258		// Data files must be untouched: first process can still write.
259		h := NewHandler(first)
260		mustRegister(t, h, "gw")
261	
262		if err := first.Close(); err != nil {
263			t.Fatal(err)
264		}
265		// After exit (including a killed process releasing the kernel lock) the
266		// directory reopens without manual cleanup.
267		again := reopenPersistent(t, dir)
268		if !again.Exists("gw") {
269			t.Fatalf("device missing after lock release and reopen")
270		}
271	}
