		sample("e1", "2024-01-02T10:00:00Z", `{"v":11}`),
		sample("e3", "2024-01-02T10:02:00Z", `{"v":13}`),
	)
	r := doRequest(t, h, http.MethodPost, "/v1/devices/gw/replay", body)
